diff --git a/src/go/calc/calc.go b/src/go/calc/calc.go
index c874eab..e594a17 100644
--- a/src/go/calc/calc.go
+++ b/src/go/calc/calc.go
@@ -8,3 +8,11 @@ func Sum(xs []int) int {
 	}
 	return total
 }
+
+// Mean returns the arithmetic mean of xs, or 0 when xs is empty.
+func Mean(xs []int) float64 {
+	if len(xs) == 0 {
+		return 0
+	}
+	return float64(Sum(xs)) / float64(len(xs))
+}
diff --git a/src/go/calc/calc_test.go b/src/go/calc/calc_test.go
index 7991fb1..9e51e01 100644
--- a/src/go/calc/calc_test.go
+++ b/src/go/calc/calc_test.go
@@ -7,3 +7,36 @@ func TestSum(t *testing.T) {
 		t.Fatalf("Sum = %d, want 6", got)
 	}
 }
+
+// Every want below is exactly representable in float64, so equality is the
+// oracle — no tolerance needed.
+func TestMean(t *testing.T) {
+	cases := []struct {
+		name string
+		xs   []int
+		want float64
+	}{
+		{"empty", []int{}, 0},
+		{"nil", nil, 0},
+		{"single", []int{5}, 5},
+		{"whole", []int{1, 2, 3}, 2},
+		{"fractional", []int{1, 2}, 1.5},
+		{"negatives cancel", []int{-3, 3}, 0},
+	}
+	for _, c := range cases {
+		t.Run(c.name, func(t *testing.T) {
+			if got := Mean(c.xs); got != c.want {
+				t.Fatalf("Mean(%v) = %v, want %v", c.xs, got, c.want)
+			}
+		})
+	}
+}
+
+// Invariant: for a non-empty slice, Mean times the length recovers Sum.
+func TestMeanAgreesWithSum(t *testing.T) {
+	for _, xs := range [][]int{{5}, {1, 2}, {1, 2, 3}, {-3, 3}, {7, 7, 7, 7}} {
+		if got := Mean(xs) * float64(len(xs)); got != float64(Sum(xs)) {
+			t.Errorf("Mean(%v)*%d = %v, want Sum = %d", xs, len(xs), got, Sum(xs))
+		}
+	}
+}

